<script setup>
import { ref, reactive, onMounted } from 'vue';
import Icon from '../components/Icon.vue';
import Modal from '../components/Modal.vue';
import { state, isDemo, notify, report } from '../lib/workspace.js';
import { post } from '../lib/api.js';
const tasks = ref([]), loading = ref(false), busy = ref(false), error = ref(''), dialog = ref(''), target = ref(null);
const form = reactive({ agentId: '', taskDesc: '', taskCron: '0 0 9 * * *', userMessage: '', maxRound: 3, maxRetry: 2, maxPace: 5, taskStatus: 1 });
const demoTasks = [{ taskId: 'demo-task-1', agentId: 'demo-research', taskDesc: '每日灵感简报', taskCron: '0 0 9 * * *', taskParam: '{"maxRound":3,"maxRetry":2,"maxPace":5,"userMessage":"整理值得关注的 AI 产品与技术资讯。"}', taskStatus: 1 }, { taskId: 'demo-task-2', agentId: 'demo-write', taskDesc: '每周内容回顾', taskCron: '0 0 18 * * FRI', taskParam: '{"maxRound":3,"maxRetry":2,"maxPace":5,"userMessage":"回顾本周的写作灵感，整理下一周的内容方向。"}', taskStatus: 0 }];
const cronLabel = cron => ({ '0 0 9 * * *': '每天 09:00', '0 0 9 * * MON-FRI': '工作日 09:00', '0 0 18 * * FRI': '每周五 18:00' })[cron] || cron;
async function load() { loading.value = true; error.value = ''; try { tasks.value = isDemo.value ? demoTasks : (await post('/user/task/list')) || []; } catch (e) { error.value = e.message; } finally { loading.value = false; } }
function open(task = null) {
  target.value = task; error.value = ''; let params = {};
  if (task) { try { params = JSON.parse(task.taskParam); } catch { error.value = '原任务参数无法解析，请补全任务内容后重新保存。'; } }
  Object.assign(form, { agentId: task?.agentId || state.agents[0]?.agentId || '', taskDesc: task?.taskDesc || '', taskCron: task?.taskCron || '0 0 9 * * *', userMessage: params.userMessage || '', maxRound: params.maxRound || 3, maxRetry: params.maxRetry || 2, maxPace: params.maxPace || 5, taskStatus: task?.taskStatus ?? 1 }); dialog.value = 'edit';
}
async function save() {
  if (busy.value) return;
  if (form.taskCron.trim().split(/\s+/).length !== 6) { error.value = '定时规则需要六个字段：秒 分 时 日 月 周'; return; }
  if (![form.maxRound, form.maxRetry, form.maxPace].every(n => Number.isInteger(n) && n >= 1)) { error.value = '执行参数必须是大于等于 1 的整数'; return; }
  busy.value = true; error.value = '';
  try { const json = { agentId: form.agentId, taskDesc: form.taskDesc.trim(), taskCron: form.taskCron.trim(), taskStatus: form.taskStatus, taskParam: JSON.stringify({ maxRound: form.maxRound, maxRetry: form.maxRetry, maxPace: form.maxPace, userMessage: form.userMessage.trim() }), ...(target.value ? { taskId: target.value.taskId } : {}) };
    if (!isDemo.value) await post('/user/task/' + (target.value ? 'update' : 'insert'), { json }); else if (target.value) Object.assign(target.value, json); else demoTasks.unshift({ ...json, taskId: 'demo-task-' + Date.now() });
    dialog.value = ''; await load(); notify(isDemo.value ? '演示定时配置已保存，不会实际执行' : '定时配置已保存，等待服务端刷新注册');
  } catch (e) { error.value = e.message; } finally { busy.value = false; }
}
async function toggle(task) { if (busy.value) return; busy.value = true; try { const taskStatus = task.taskStatus === 1 ? 0 : 1; if (!isDemo.value) await post('/user/task/toggle', { query: { taskId: task.taskId, taskStatus } }); task.taskStatus = taskStatus; notify(taskStatus ? '启用配置已保存' : '暂停配置已保存'); } catch (e) { report(e); } finally { busy.value = false; } }
async function remove() { if (busy.value) return; busy.value = true; try { if (!isDemo.value) await post('/user/task/delete', { query: { taskId: target.value.taskId } }); else demoTasks.splice(demoTasks.indexOf(target.value), 1); dialog.value = ''; await load(); notify('定时配置已删除'); } catch (e) { error.value = e.message; } finally { busy.value = false; } }
onMounted(load);
</script>
<template>
  <div class="page"><header class="page-heading"><div><div class="eyebrow">GOOD WORK HAS A RHYTHM</div><h1>让好习惯，自动发生</h1><p>安排重复的工作，把每天的时间还给你。</p></div><button class="primary-button" @click="open()"><Icon name="plus" :size="17" />创建定时任务</button></header><section class="schedule-banner"><div class="schedule-clock" aria-hidden="true"><Icon name="clock" :size="55" /><span>✳</span></div><div><h2>清晨的一份简报，周五的一次回顾。</h2><p>选好时间，写下目标，让智能体成为有节奏的工作伙伴。</p></div></section><div class="toolbar"><h2 class="subheading">我的任务 <span class="count">{{ tasks.length }}</span></h2><button class="text-button" @click="load"><Icon name="refresh" :size="16" />刷新配置</button></div><div v-if="isDemo" class="demo-notice"><i class="tiny-dot"></i>演示定时配置 · 不会实际调度或执行</div><div v-if="error && !dialog" class="form-error">{{ error }}</div><div v-if="loading" class="loading-placeholder">正在读取定时配置…</div><div v-else-if="tasks.length" class="data-table-wrap"><table class="data-table schedules-table"><thead><tr><th>任务</th><th>执行伙伴</th><th>定时规则</th><th>配置状态</th><th></th></tr></thead><tbody><tr v-for="task in tasks" :key="task.taskId"><td class="title-cell"><div class="row"><span class="quick-icon sage"><Icon name="clock" :size="18" /></span><span>{{ task.taskDesc }}</span></div></td><td>{{ state.agents.find(a => a.agentId === task.agentId)?.agentName || task.agentId }}</td><td><span class="cron-label">{{ cronLabel(task.taskCron) }}</span><small v-if="cronLabel(task.taskCron) !== task.taskCron" class="cron-code">{{ task.taskCron }}</small></td><td><button class="toggle-control" :class="{ on: task.taskStatus === 1 }" role="switch" :aria-checked="task.taskStatus === 1" :aria-label="'启用 ' + task.taskDesc" :disabled="busy" @click="toggle(task)"><span></span></button><span class="toggle-label">{{ task.taskStatus === 1 ? '已启用' : '已暂停' }}</span></td><td><div class="actions"><button class="icon-button" aria-label="编辑定时任务" @click="open(task)"><Icon name="pen" :size="16" /></button><button class="icon-button" aria-label="删除定时任务" @click="target = task; dialog = 'delete'; error = ''"><Icon name="trash" :size="16" /></button></div></td></tr></tbody></table></div><div v-else class="empty-state"><Icon name="clock" :size="40" /><h2>给工作一个轻松的节奏</h2><p>从你的第一项定时任务开始。</p><button class="secondary-button" @click="open()">创建定时任务</button></div><div class="schedule-info info-note"><Icon name="help" :size="18" /><span>时间遵循服务器的调度时区。保存或启用配置后，服务端会刷新调度注册；当前页面展示配置状态，不代表实际运行结果。</span></div></div>
  <Modal v-if="dialog === 'edit'" :title="target ? '调整任务节奏' : '安排一项定时任务'" wide @close="!busy && (dialog = '')"><form class="modal-body form-stack" @submit.prevent="save"><div class="form-grid"><label>任务名称<input v-model="form.taskDesc" required placeholder="例如：每日灵感简报" /></label><label>执行伙伴<select v-model="form.agentId" required><option value="" disabled>选择智能体</option><option v-for="agent in state.agents" :key="agent.agentId" :value="agent.agentId">{{ agent.agentName }}</option></select></label></div><label>让它做什么？<textarea v-model="form.userMessage" required placeholder="清楚描述本次任务的目标与输出要求" /></label><label>执行时间<select :value="form.taskCron" @change="form.taskCron = $event.target.value"><option value="0 0 9 * * *">每天 09:00</option><option value="0 0 9 * * MON-FRI">工作日 09:00</option><option value="0 0 18 * * FRI">每周五 18:00</option><option :value="form.taskCron">自定义规则</option></select></label><label>定时表达式<input v-model="form.taskCron" required placeholder="秒 分 时 日 月 周" /><small>六字段 Spring Cron，使用服务器调度时区。</small></label><div class="form-grid three-fields"><label>最大轮次<input v-model.number="form.maxRound" type="number" min="1" required /></label><label>最大重试<input v-model.number="form.maxRetry" type="number" min="1" required /></label><label>最大步数<input v-model.number="form.maxPace" type="number" min="1" required /></label></div><label class="checkbox-line"><input v-model="form.taskStatus" type="checkbox" :true-value="1" :false-value="0" />保存为启用状态</label><div v-if="error" class="form-error">{{ error }}</div><div class="form-actions"><button type="button" class="secondary-button" :disabled="busy" @click="dialog = ''">取消</button><button class="primary-button" :disabled="busy">{{ busy ? '保存中…' : '保存定时任务' }}</button></div></form></Modal>
  <Modal v-if="dialog === 'delete'" title="删除这项定时任务？" @close="!busy && (dialog = '')"><div class="modal-body form-stack"><p class="small muted">「{{ target.taskDesc }}」的定时配置将被删除，此操作无法恢复。</p><div v-if="error" class="form-error">{{ error }}</div><button class="danger-button" :disabled="busy" @click="remove">确认删除</button></div></Modal>
</template>
